async function safeWalk(x: number, z: number, tries = 3): Promise<boolean> {
  for (let i = 0; i < tries; i++) {
    const dlg = sdk.getDialog();
    if (dlg?.isOpen) { await bot.dismissBlockingUI(); await sdk.waitForTicks(1); }
    try {
      const r = await bot.walkTo(x, z);
      if (r.success) return true;
    } catch (e) { /* ignore */ }
    await sdk.waitForTicks(2);
  }
  return false;
}

